INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist File-Storage dasselbe wie Block-Storage?', 2, '[{"text": "Nein", "correct": true, "because": "Dateien vs. Blöcke"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Ansätze"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt File-Storage?', 3, '[{"text": "Daten als Dateien organisieren", "correct": true, "because": "Hierarchisches System"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Nicht primär"}, {"text": "Netzwerke verbinden", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien sind typisch für File-Storage?', 5, '[{"text": "NAS", "correct": true, "because": "Network Attached Storage"}, {"text": "SMB", "correct": true, "because": "Server Message Block"}, {"text": "Papierarchivierung", "correct": false, "because": "Nicht digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) File-Storage nutzt ein hierarchisches Dateisystem. b) Es speichert Daten nur lokal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Netzwerk"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei File-Storage?', 4, '[{"text": "Dateistruktur", "correct": false, "because": "Grundlage"}, {"text": "Zugriffsrechte", "correct": false, "because": "Sicherheit"}, {"text": "Papiergröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob File-Storage immer lokal ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Netzwerkspeicher"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wird häufig für File-Storage genutzt?', 3, '[{"text": "NFS", "correct": true, "because": "Network File System"}, {"text": "HTTP", "correct": false, "because": "Webprotokoll"}, {"text": "FTP", "correct": false, "because": "Dateitransfer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet File-Storage?', 5, '[{"text": "Einfache Verwaltung", "correct": true, "because": "Hierarchisch"}, {"text": "Netzwerkzugriff", "correct": true, "because": "Gemeinsame Nutzung"}, {"text": "Papierersparnis", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) File-Storage ist hierarchisch organisiert. b) Es ist nur für große Datenmengen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Größen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für File-Storage?', 4, '[{"text": "Dateisystem", "correct": false, "because": "Grundlage"}, {"text": "Speichermedium", "correct": false, "because": "Hardware nötig"}, {"text": "Papierdokumente", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist File-Storage immer netzwerkbasiert?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokal"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Systeme nutzen File-Storage?', 4, '[{"text": "NAS", "correct": true, "because": "Network Attached Storage"}, {"text": "PCs", "correct": true, "because": "Lokale Dateien"}, {"text": "Drucker", "correct": false, "because": "Kein Speicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass File-Storage keine Sicherheitsfunktionen hat. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Zugriffsrechte möglich"}, {"text": "Ja", "correct": false, "because": "Sicherheit integrierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei File-Storage?', 3, '[{"text": "Zugriffskontrolle", "correct": true, "because": "Sicherheit"}, {"text": "Papierformate", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Sicherheit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) File-Storage unterstützt Dateifreigabe. b) Es ist nur für lokale Speicherung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Netzwerk"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle werden für File-Storage verwendet?', 5, '[{"text": "SMB", "correct": true, "because": "Windows-Netzwerke"}, {"text": "NFS", "correct": true, "because": "Unix-Systeme"}, {"text": "HTTP", "correct": false, "because": "Webprotokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei File-Storage unwichtig?', 3, '[{"text": "Dateistruktur", "correct": false, "because": "Grundlage"}, {"text": "Zugriffsrechte", "correct": false, "because": "Sicherheit"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann File-Storage mit Cloud-Diensten kombiniert werden?', 3, '[{"text": "Ja", "correct": true, "because": "Hybridlösungen"}, {"text": "Nein", "correct": false, "because": "Kombination möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob File-Storage für Datenbanken optimiert ist?', 2, '[{"text": "Nein", "correct": true, "because": "Block-Storage besser"}, {"text": "Ja", "correct": false, "because": "Dateifokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für File-Storage zentral?', 4, '[{"text": "Hierarchisches Dateisystem", "correct": true, "because": "Kernprinzip"}, {"text": "Papierdokumente", "correct": false, "because": "Irrelevant"}, {"text": "Blockzugriff", "correct": false, "because": "Anderes System"}]');
